//! The schema catalog the `catalog_*` functions answer from.
//!
//! The data is generated by `build.rs` from `gnoblin-schema`'s files: every class with its properties, methods and
//! signals as static slices. A class id is its position in [`CLASSES`] plus one; a member id is its position in its class's
//! list of that kind plus one. Ids are stable for the life of the process and only meaningful against the core that
//! issued them, which is why the SDK looks names up once.
//!
//! A bare class name (`window`) is a class of the `tree` namespace, the one a shell edits; any other namespace is written
//! `namespace.object` (`gnoblin.session`).

use gnoblin_core_abi::{self as abi, GnoblinMember};

/// What a property reads as before anything wrote it, when the schema says (`opacity` is 1, a `scale` 1): the mirror holds only
/// the properties that differ from their defaults.
#[derive(Clone, Copy, Debug, PartialEq)]
pub(crate) enum DefaultDef {
    /// The schema gives none: the empty value of the property's kind.
    None,
    Bool(bool),
    Int(i64),
    Uint(u64),
    Double(f64),
    Text(&'static str),
    Numbers(&'static [f64]),
    Texts(&'static [&'static str]),
}

/// One property, method or signal.
pub(crate) struct MemberDef {
    pub name: &'static str,
    pub value_kind: u32,
    pub flags: u32,
    pub args: &'static [u32],
    pub default: DefaultDef,
}

/// One class with its members.
pub(crate) struct ClassDef {
    pub namespace: &'static str,
    pub name: &'static str,
    pub properties: &'static [MemberDef],
    pub methods: &'static [MemberDef],
    pub signals: &'static [MemberDef],
}

include!(concat!(env!("OUT_DIR"), "/catalog_data.rs"));

/// The class a name refers to, as an id (never zero).
pub(crate) fn class_id(name: &str) -> Option<u32> {
    let (namespace, object) = match name.rsplit_once('.') {
        Some((namespace, object)) => (namespace, object),
        None => ("tree", name),
    };
    CLASSES
        .iter()
        .position(|class| class.namespace == namespace && class.name == object)
        .map(|position| position as u32 + 1)
}

/// The class with id `id`.
pub(crate) fn class(id: u32) -> Option<&'static ClassDef> {
    let position = usize::try_from(id.checked_sub(1)?).ok()?;
    CLASSES.get(position)
}

fn members_of(class: &'static ClassDef, kind: u32) -> Option<&'static [MemberDef]> {
    match kind {
        abi::MEMBER_PROPERTY => Some(class.properties),
        abi::MEMBER_METHOD => Some(class.methods),
        abi::MEMBER_SIGNAL => Some(class.signals),
        _ => None,
    }
}

/// The ABI description of the member at `position` of `defs`.
fn describe(defs: &'static [MemberDef], position: usize, kind: u32) -> GnoblinMember {
    let def = &defs[position];
    GnoblinMember {
        size: size_of::<GnoblinMember>() as u32,
        id: position as u32 + 1,
        kind,
        value_kind: def.value_kind,
        flags: def.flags,
        arg_count: def.args.len() as u32,
        arg_kinds: def.args.as_ptr(),
    }
}

/// Looks a member up by name.
pub(crate) fn member(class_id: u32, kind: u32, name: &str) -> Result<GnoblinMember, String> {
    let class = class(class_id).ok_or_else(|| format!("no class with id {class_id}"))?;
    let defs = members_of(class, kind).ok_or_else(|| format!("{kind} is not a member kind"))?;
    let position = defs
        .iter()
        .position(|def| def.name == name)
        .ok_or_else(|| format!("class `{}` has no such member `{name}`", class.name))?;
    Ok(describe(defs, position, kind))
}

/// Every member of one kind of a class, in declaration order.
pub(crate) fn members(class_id: u32, kind: u32) -> Result<Vec<GnoblinMember>, String> {
    let class = class(class_id).ok_or_else(|| format!("no class with id {class_id}"))?;
    let defs = members_of(class, kind).ok_or_else(|| format!("{kind} is not a member kind"))?;
    Ok((0..defs.len()).map(|position| describe(defs, position, kind)).collect())
}

/// Checks that `signal` is a signal of `class`.
pub(crate) fn check_signal(class_id: u32, signal: u32) -> Result<(), String> {
    let class = class(class_id).ok_or_else(|| format!("no class with id {class_id}"))?;
    let position =
        usize::try_from(signal.checked_sub(1).ok_or("signal id zero")?).map_err(|_| "signal id too large")?;
    if position < class.signals.len() {
        Ok(())
    } else {
        Err(format!("class `{}` has no signal with id {signal}", class.name))
    }
}

/// The signal id of `name` in `class`, for the compositor side that publishes by name.
pub(crate) fn signal_id(class_id: u32, name: &str) -> Option<u32> {
    let class = class(class_id)?;
    class
        .signals
        .iter()
        .position(|def| def.name == name)
        .map(|position| position as u32 + 1)
}

/// The class of the tree namespace called `name` (`window`), zero when the catalog has none: what a node of that class is, as an
/// id. A node's class in the mirror is its schema name, so this is how a mirror class becomes a catalog class.
pub(crate) fn tree_class_id(name: &str) -> u32 {
    class_id(name).unwrap_or(0)
}

/// The name a class is looked up by: `window` for a tree class, `namespace.object` for another namespace's.
pub(crate) fn class_label(id: u32) -> Option<String> {
    let class = class(id)?;
    Some(if class.namespace == "tree" {
        class.name.to_owned()
    } else {
        format!("{}.{}", class.namespace, class.name)
    })
}

/// The property of `class_id` with id `prop` (a position plus one), with its class.
pub(crate) fn property_def(class_id: u32, prop: u32) -> Option<&'static MemberDef> {
    let class = class(class_id)?;
    class.properties.get(usize::try_from(prop.checked_sub(1)?).ok()?)
}

/// The method of `class_id` with id `method`.
pub(crate) fn method_def(class_id: u32, method: u32) -> Option<&'static MemberDef> {
    let class = class(class_id)?;
    class.methods.get(usize::try_from(method.checked_sub(1)?).ok()?)
}

/// The id of the property of `class_id` called `name`.
pub(crate) fn property_id(class_id: u32, name: &str) -> Option<u32> {
    let class = class(class_id)?;
    class
        .properties
        .iter()
        .position(|def| def.name == name)
        .map(|position| position as u32 + 1)
}

/// The signal of `class_id` with id `signal`.
#[cfg(test)]
pub(crate) fn signal_def(class_id: u32, signal: u32) -> Option<&'static MemberDef> {
    let class = class(class_id)?;
    class.signals.get(usize::try_from(signal.checked_sub(1)?).ok()?)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tree_classes_are_found_by_their_bare_name() {
        let window = class_id("window").expect("tree.window exists");
        assert_eq!(class(window).unwrap().namespace, "tree");
        assert_eq!(class_id("tree.window"), Some(window));
    }

    #[test]
    fn another_namespace_needs_its_qualified_name() {
        let session = class_id("gnoblin.session").expect("gnoblin.session exists");
        assert_eq!(class(session).unwrap().namespace, "gnoblin");
        // `window` also exists in the `gnoblin` namespace, and the bare name must still mean the tree's.
        let bare = class_id("window").unwrap();
        let qualified = class_id("gnoblin.window").unwrap();
        assert_ne!(bare, qualified);
    }

    #[test]
    fn unknown_names_and_ids_are_none() {
        assert_eq!(class_id("no_such_class"), None);
        assert_eq!(class_id("nonsense.window"), None);
        assert!(class(0).is_none());
        assert!(class(u32::MAX).is_none());
    }

    #[test]
    fn a_property_is_described_with_its_kind_and_flags() {
        let window = class_id("window").unwrap();
        let title = member(window, abi::MEMBER_PROPERTY, "title").unwrap();
        assert_eq!(title.kind, abi::MEMBER_PROPERTY);
        assert_eq!(title.value_kind, abi::VALUE_TEXT);
        assert_eq!(title.flags & abi::MEMBER_READONLY, abi::MEMBER_READONLY);
        let fullscreen = member(window, abi::MEMBER_PROPERTY, "fullscreen").unwrap();
        assert_eq!(fullscreen.value_kind, abi::VALUE_BOOL);
        assert_eq!(fullscreen.flags & abi::MEMBER_READONLY, 0);
    }

    #[test]
    fn member_ids_are_stable_positions() {
        let window = class_id("window").unwrap();
        let all = members(window, abi::MEMBER_PROPERTY).unwrap();
        for (position, member) in all.iter().enumerate() {
            assert_eq!(member.id as usize, position + 1);
        }
        let named = member_by_id_name(window, abi::MEMBER_PROPERTY, 1);
        assert_eq!(member(window, abi::MEMBER_PROPERTY, named).unwrap().id, 1);
    }

    fn member_by_id_name(class_id: u32, kind: u32, id: u32) -> &'static str {
        let class = class(class_id).unwrap();
        members_of(class, kind).unwrap()[id as usize - 1].name
    }

    #[test]
    fn signals_carry_their_field_kinds() {
        let tree = class_id("tree").unwrap();
        let attached = member(tree, abi::MEMBER_SIGNAL, "attached").unwrap();
        assert!(attached.arg_count >= 1);
        assert_eq!(signal_id(tree, "attached"), Some(attached.id));
        assert!(check_signal(tree, attached.id).is_ok());
        assert!(check_signal(tree, 0).is_err());
        assert!(check_signal(tree, 10_000).is_err());
    }

    #[test]
    #[allow(unsafe_code)]
    fn the_lock_password_is_a_secret_argument() {
        let lock = class_id("lock").unwrap();
        let authenticate = member(lock, abi::MEMBER_METHOD, "authenticate").unwrap();
        assert_eq!(authenticate.flags & abi::MEMBER_SECRET, abi::MEMBER_SECRET);
        assert_eq!(authenticate.arg_count, 1);
        // SAFETY: `arg_kinds` points at `arg_count` kinds in static storage.
        let kinds = unsafe { std::slice::from_raw_parts(authenticate.arg_kinds, 1) };
        assert_eq!(kinds, [abi::VALUE_SECRET]);
    }

    #[test]
    fn the_hash_is_not_zero_and_the_catalog_is_not_empty() {
        assert_ne!(CATALOG_HASH, 0);
        assert!(CLASSES.len() > 10);
    }
}
